func Allow(store Store, key string, now time.Time, period time.Duration, burst int) bool {
	tat := store.Get(key) // zero if unseen
	if tat.Before(now) {
		tat = now
	}
	allowAt := tat.Add(-period * time.Duration(burst))
	if now.Before(allowAt) {
		return false
	}
	store.Set(key, tat.Add(period))
	return true
}
